set -euo pipefail; test "$(git rev-parse HEAD)" = "0ad9595b6d1b9a1db69b5a616a5f17932c424ee7"; git status --short; python3 - <<'PY'
from pathlib import Path

def replace(path, old, new):
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f'missing pattern in {path}: {old[:120]!r}')
    p.write_text(text.replace(old, new, 1))

# Bottom navigation: user-facing Climate -> Plugs, keep internal kind='climate'.
path = 'apps/mobile/src/components/AppBottomNavigation.tsx'
replace(path, "import { IconClock, IconSettings, IconTemperature } from '@tabler/icons-react';", "import { IconClock, IconPlug, IconSettings } from '@tabler/icons-react';")
replace(path, "        <IconTemperature
          className="dashboard-nav__icon app-bottom-nav__icon"
          aria-hidden="true"
        />", "        <IconPlug
          className="dashboard-nav__icon app-bottom-nav__icon"
          aria-hidden="true"
        />")

# Localized tab labels only; no new locale schema keys.
locale_values = {
    'en.ts': ('Climate', 'Plugs'),
    'pl.ts': ('Klimat', 'Gniazdka'),
    'de.ts': ('Klima', 'Steckdosen'),
    'es.ts': ('Clima', 'Enchufes'),
    'fr.ts': ('Climat', 'Prises'),
    'it.ts': ('Clima', 'Prese'),
    'ptBr.ts': ('Clima', 'Tomadas'),
}
for filename, (old_value, new_value) in locale_values.items():
    path = f'apps/mobile/src/app/locales/{filename}'
    replace(path, f"climateTab: '{old_value}'", f"climateTab: '{new_value}'")

# Dashboard: saved Shelly plugs are the primary climate-tab surface. Existing automation cards stay unchanged.
path = 'apps/mobile/src/screens/AutomationDashboardScreen.tsx'
replace(path, "  IconDotsVertical,
  IconPlus,
  IconTemperature", "  IconDotsVertical,
  IconPlug,
  IconPlus,
  IconTemperature")
replace(path, "import { useInstalledAutomationStore } from '../flows/installations/store.js';", "import { useInstalledAutomationStore } from '../flows/installations/store.js';
import {
  useHardwareSetupDraftStore,
  type ShellyDraftDevice
} from '../flows/hardware-setup/setupDraftStore.js';")
insert_after = "const AutomationCard = ({ installation, onOpen }: AutomationCardProps) =>
  installation.kind === 'time' ? (
    <TimeAutomationCard installation={installation} onOpen={onOpen} />
  ) : (
    <ClimateAutomationCard installation={installation} onOpen={onOpen} />
  );
"
plain_card = insert_after + "
const PlainPlugCard = ({
  device,
  onAddAutomation
}: {
  device: ShellyDraftDevice;
  onAddAutomation(): void;
}) => {
  const { t } = useTranslation();

  return (
    <article className="automation-card plug-card plug-card--unconfigured">
      <header className="automation-card__header">
        <span className="automation-card__leading-icon" aria-hidden="true">
          <IconPlug className="automation-card__icon" />
        </span>
        <div className="automation-card__identity">
          <h2>{device.name}</h2>
          <p>{t('dashboard.emptyCategory')}</p>
        </div>
      </header>
      <button
        className="primary-action plug-card__automation-action"
        type="button"
        onClick={onAddAutomation}
      >
        {t('dashboard.addAutomation')}
      </button>
    </article>
  );
};
"
replace(path, insert_after, plain_card)
replace(path, "  onAddAutomation(kind: AppNavigationKind): void;", "  onAddAutomation(kind: AppNavigationKind, shellyId?: string): void;")
replace(path, "  const installations = useInstalledAutomationStore((state) => state.installations);
  const queryClient = useQueryClient();
  const hasClimate = installations.some((installation) => installation.kind !== 'time');", "  const installations = useInstalledAutomationStore((state) => state.installations);
  const shellyDevices = useHardwareSetupDraftStore((state) => state.shellyDevices);
  const queryClient = useQueryClient();
  const climateInstallations = installations.filter(
    (installation): installation is ClimateInstalledAutomation => installation.kind !== 'time'
  );
  const hasClimate = shellyDevices.length > 0 || climateInstallations.length > 0;")
replace(path, "  const visibleInstallations = installations.filter((installation) =>
    activeKind === 'time' ? installation.kind === 'time' : installation.kind !== 'time'
  );

  return (", "  const visibleInstallations = installations.filter((installation) =>
    activeKind === 'time' ? installation.kind === 'time' : installation.kind !== 'time'
  );
  const normalizedBaseUrl = (value: string) => value.trim().replace(/\/+$/, '').toLowerCase();
  const matchedClimateInstallationIds = new Set<string>();
  const plugEntries = shellyDevices.map((device) => {
    const installation =
      climateInstallations.find(
        (candidate) =>
          normalizedBaseUrl(candidate.shelly.baseUrl) === normalizedBaseUrl(device.baseUrl)
      ) ?? null;
    if (installation) matchedClimateInstallationIds.add(installation.id);
    return { device, installation };
  });
  const unmatchedClimateInstallations = climateInstallations.filter(
    (installation) => !matchedClimateInstallationIds.has(installation.id)
  );
  const hasPlugEntries = plugEntries.length > 0 || unmatchedClimateInstallations.length > 0;

  return (")
replace(path, "        <h1>{t('dashboard.title')}</h1>", "        <h1>{activeKind === 'climate' ? t('dashboard.climateTab') : t('dashboard.title')}</h1>")
old_section = "        {visibleInstallations.length > 0 ? (
          visibleInstallations.map((installation) => (
            <AutomationCard
              key={installation.id}
              installation={installation}
              onOpen={onOpenInstallation}
            />
          ))
        ) : (
          <div className="dashboard-kind-empty" role="status">
            {activeKind === 'time' ? (
              <IconClock className="dashboard-kind-empty__icon" aria-hidden="true" />
            ) : (
              <IconTemperature
                className="dashboard-kind-empty__icon"
                aria-hidden="true"
              />
            )}
            <strong>{t('dashboard.emptyCategory')}</strong>
          </div>
        )}"
new_section = "        {activeKind === 'time' ? (
          visibleInstallations.length > 0 ? (
            visibleInstallations.map((installation) => (
              <AutomationCard
                key={installation.id}
                installation={installation}
                onOpen={onOpenInstallation}
              />
            ))
          ) : (
            <div className="dashboard-kind-empty" role="status">
              <IconClock className="dashboard-kind-empty__icon" aria-hidden="true" />
              <strong>{t('dashboard.emptyCategory')}</strong>
            </div>
          )
        ) : hasPlugEntries ? (
          <>
            {plugEntries.map(({ device, installation }) =>
              installation ? (
                <ClimateAutomationCard
                  key={installation.id}
                  installation={installation}
                  onOpen={onOpenInstallation}
                />
              ) : (
                <PlainPlugCard
                  key={`plug:${device.id}`}
                  device={device}
                  onAddAutomation={() => onAddAutomation('climate', device.id)}
                />
              )
            )}
            {unmatchedClimateInstallations.map((installation) => (
              <ClimateAutomationCard
                key={installation.id}
                installation={installation}
                onOpen={onOpenInstallation}
              />
            ))}
          </>
        ) : (
          <div className="dashboard-kind-empty" role="status">
            <IconPlug className="dashboard-kind-empty__icon" aria-hidden="true" />
            <strong>{t('dashboard.emptyCategory')}</strong>
          </div>
        )}"
replace(path, old_section, new_section)

# Existing FAB remains as fallback for adding a brand-new system; per-plug automation uses the card action.

# Route known plug context into the existing intent/setup flow.
path = 'apps/mobile/src/routes/AppRoutes.tsx'
replace(path, "import { useInstalledAutomationStore } from '../flows/installations/store.js';", "import { useInstalledAutomationStore } from '../flows/installations/store.js';
import { useHardwareSetupDraftStore } from '../flows/hardware-setup/setupDraftStore.js';")
replace(path, "  | { type: 'intent'; sourceKind: AppNavigationKind }
  | { type: 'setup'; intent: SetupRouteIntent; sourceKind: AppNavigationKind }", "  | { type: 'intent'; sourceKind: AppNavigationKind; shellyId?: string }
  | {
      type: 'setup';
      intent: SetupRouteIntent;
      sourceKind: AppNavigationKind;
      shellyId?: string;
    }")
replace(path, "      : { type: 'intent', sourceKind: route.sourceKind };", "      : {
          type: 'intent',
          sourceKind: route.sourceKind,
          ...(route.shellyId ? { shellyId: route.shellyId } : {})
        };")
replace(path, "  const installations = useInstalledAutomationStore((state) => state.installations);", "  const installations = useInstalledAutomationStore((state) => state.installations);
  const selectShellyDevice = useHardwareSetupDraftStore((state) => state.selectShellyDevice);")
replace(path, "  const selectIntent = (intent: SetupIntent) => {
    const nextKind = setupKindForIntent(intent);
    navigate({ type: 'setup', intent, sourceKind: nextKind });
  };", "  const selectIntent = (intent: SetupIntent, shellyId?: string) => {
    const nextKind = setupKindForIntent(intent);
    if (shellyId) selectShellyDevice(shellyId);
    navigate({
      type: 'setup',
      intent,
      sourceKind: nextKind,
      ...(shellyId ? { shellyId } : {})
    });
  };")
replace(path, "        onSelect={selectIntent}", "        onSelect={(intent) => selectIntent(intent, route.shellyId)}")
old_add = "        onAddAutomation={(kind) =>
          kind === 'time'
            ? navigate({ type: 'setup', intent: 'time', sourceKind: 'time' })
            : navigate({ type: 'intent', sourceKind: 'climate' })
        }"
new_add = "        onAddAutomation={(kind, shellyId) => {
          if (shellyId) selectShellyDevice(shellyId);
          if (kind === 'time') {
            navigate({ type: 'setup', intent: 'time', sourceKind: 'time' });
            return;
          }
          navigate({
            type: 'intent',
            sourceKind: 'climate',
            ...(shellyId ? { shellyId } : {})
          });
        }}"
replace(path, old_add, new_add)
replace(path, "        setupIntent={route.intent}", "        setupIntent={route.intent}
        {...(route.shellyId ? { fixedShellyId: route.shellyId } : {})}")
replace(path, "              : { type: 'intent', sourceKind: route.sourceKind }
          )", "              : {
                  type: 'intent',
                  sourceKind: route.sourceKind,
                  ...(route.shellyId ? { shellyId: route.shellyId } : {})
                }
          )")

# Setup entered from a plug: hide the redundant Shelly tab and Shelly selector.
path = 'apps/mobile/src/screens/hardware-setup/HardwareSetupScreen.tsx'
replace(path, "const availableTabsForIntent = (setupIntent?: SetupIntent) =>
  setupIntent === 'time' ? TIME_HARDWARE_TABS : CLIMATE_HARDWARE_TABS;", "const availableTabsForIntent = (setupIntent?: SetupIntent, fixedShellyId?: string) => {
  if (setupIntent === 'time') return TIME_HARDWARE_TABS;
  return fixedShellyId
    ? CLIMATE_HARDWARE_TABS.filter((tab) => tab.id !== 'shelly')
    : CLIMATE_HARDWARE_TABS;
};")
