          onOpenDiagnostics={() => selectTab('diagnostics')}", "          selectablePresets={selectableRulePresets}
          showShellySelector={!fixedShellyId}
          onOpenDiagnostics={() => selectTab('diagnostics')}")

path = 'apps/mobile/src/screens/hardware-setup/pages/RuleSetupPage.tsx'
replace(path, "  selectablePresets?: readonly RulePresetId[];
  onOpenDiagnostics?: () => void;", "  selectablePresets?: readonly RulePresetId[];
  showShellySelector?: boolean;
  onOpenDiagnostics?: () => void;")
replace(path, "  flow,
  selectablePresets = ALL_RULE_PRESETS,
  onOpenDiagnostics", "  flow,
  selectablePresets = ALL_RULE_PRESETS,
  showShellySelector = true,
  onOpenDiagnostics")
old_field = "      <label className="field">
        {t('hardware.rule.selectedShelly')}
        <span className="select-control">
          <select
            value={flow.selectedShellyId ?? ''}
            onChange={(event) => flow.selectShellyDevice(event.currentTarget.value)}
          >
            <option value="" disabled>
              {t('hardware.rule.noShellySelected')}
            </option>
            {flow.shellyDevices.map((device) => (
              <option key={device.id} value={device.id}>
                {device.name}
              </option>
            ))}
          </select>
        </span>
      </label>"
new_field = "      {showShellySelector && (
        <label className="field">
          {t('hardware.rule.selectedShelly')}
          <span className="select-control">
            <select
              value={flow.selectedShellyId ?? ''}
              onChange={(event) => flow.selectShellyDevice(event.currentTarget.value)}
