              {flow.shellyDevices.map((device) => (
                <option key={device.id} value={device.id}>
                  {device.name}
                </option>
              ))}
            </select>
          </span>
        </label>
      )}"
replace(path, old_field, new_field)

# Small style only inside existing controlled dashboard stylesheet.
p = Path('apps/mobile/src/screens/AutomationDashboardScreen.css')
text = p.read_text()
if '.plug-card__automation-action' not in text:
    text += "
